    /// forge-lint: disable-next-line(pascal-case-struct)
    struct SESwapPathExactAmountIn {
        IERC20 tokenIn;
        SESwapPathStep[] steps;
        uint256 exactAmountIn;
        uint256 minAmountOut;
    }

