interface IBalancerV3StandardExchangeBatchRouterTypes {
    /// forge-lint: disable-next-line(pascal-case-struct)
    struct SESwapStepLocals {
        bool isFirstStep;
        bool isLastStep;
        IERC20 stepTokenIn;
        uint256 stepAmountIn;
    }

